TLM.f("Sancti/08-22",{"officium":"Immaculati Cordis Beatæ Mariæ Virginis","rule":["ex C11;","Gloria","Credo","Prefatio=Maria=Festivitate;"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","sections":{"Introitus":[{"k":"ref","la":"Hebr 4:16"},{"k":"text","la":"Adeámus cum fidúcia ad thronum grátiæ, ut misericórdiam consequámur, et grátiam inveniámus in auxílio opportúno."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Adeámus cum fidúcia ad thronum grátiæ, ut misericórdiam consequámur, et grátiam inveniámus in auxílio opportúno."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui in Corde beátæ Maríæ Vírginis dignum Spíritus Sancti habitáculum præparásti: concéde propítius; ut ejúsdem immaculáti Cordis festivitátem devóta mente recoléntes, secúndum cor tuum vívere valeámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 24:23-31"},{"k":"text","la":"Ego quasi vitis fructificávi suavitátem odóris: et flores mei fructus honóris et honestátis. Ego mater pulchræ dilectiónis, et timóris, et agnitiónis, et sanctæ spei. In me grátia omnis viæ et veritátis: in me omnis spes vitæ et virtútis. Transíte ad me, omnes, qui concupíscitis me, et a generatiónibus meis implémini. Spíritus enim meus super mel dulcis, et heréditas mea super mel et favum. Memória mea in generatiónes sæculórum. Qui edunt me, adhuc esúrient: et qui bibunt me, adhuc sítient. Qui audit me, non confundétur: et qui operántur in me, non peccábunt. Qui elúcidant me, vitam ætérnam habébunt."}],"Graduale":[{"k":"ref","la":"Ps 12:6"},{"k":"text","la":"Exsultábit cor meum in salutári tuo: cantábo Dómino, qui bona tríbuit mihi: et psallam nómini Dómini altíssimi."},{"k":"ref","la":"Ps 44:18"},{"k":"text","la":"Mémores erunt nóminis tui in omni generatióne et generatiónem: proptérea pópuli confitebúntur tibi in ætérnum. Allelúja, allelúja."},{"k":"ref","la":"Luc 1:46; 1:47"},{"k":"text","la":"Magníficat ánima mea Dóminum: et exsultávit spíritus meus in Deo salutári meo. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Luc 1:46-47"},{"k":"text","la":"Magníficat ánima mea Dóminum: et exsultávit spíritus meus in Deo salutári meo. Allelúja."},{"k":"text","la":"Beátam me dicent omnes generatiónes, quia ancíllam húmilem respéxit Deus. Allelúja.","mark":"V"}],"Tractus":[{"k":"rubric","la":"Prov 8:32; 8:35"},{"k":"text","la":"Nunc ergo, fílii, audíte me: Beáti qui custódiunt vias meas."},{"k":"text","la":"Audíte disciplínam et estóte sapiéntes, et nolíte abjícere eam.","mark":"V"},{"k":"text","la":"Beátus homo qui audit me, et qui vígilat ad fores meas quotídie, et obsérvat ad postes óstii mei.","mark":"V"},{"k":"text","la":"Qui me invénerit, invéniet vitam, et háuriet salútem a Dómino.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 19:25-27"},{"k":"text","la":"In illo témpore: Stabant juxta crucem Jesu mater ejus, et soror matris ejus María Cléophæ, et María Magdaléne. Cum vidísset ergo Jesus matrem, et discípulum stantem, quem diligébat, dicit matri suæ: Múlier, ecce fílius tuus. Deinde dicit discípulo: Ecce mater tua. Et ex illa hora accépit eam discípulus in sua."}],"Offertorium":[{"k":"ref","la":"Luc 1:46; 1:49"},{"k":"text","la":"Exsultávit spíritus meus in Deo salutári meo; quia fecit mihi magna qui potens est, et sanctum nomen ejus."}],"Secreta":[{"k":"text","la":"Majestáti tuæ, Dómine, Agnum immaculátum offeréntes, quǽsumus: ut corda nostra ignis ille divínus accéndat, cui Cor beátæ Maríæ Vírginis ineffabíliter inflammávit."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Joann 19:27"},{"k":"text","la":"Dixit Jesus matri suæ: Múlier, ecce fílius tuus: deinde dixit discípulo: Ecce mater tua. Et ex illa hora accépit eam discípulus in sua."}],"Postcommunio":[{"k":"text","la":"Divínis refécti munéribus te, Dómine, supplíciter exorámus: ut beátæ Maríæ Vírginis intercessióne, cujus immaculáti Cordis solémnia venerándo égimus, a præséntibus perículis liberáti, ætérnæ vitæ gáudia consequámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"79ee4401a403e164":{"t":"Heb 4, 16, Ps 44, 2\n(Hebr 4, 16) Pristupimo s pouzdanjem k prijestolju milosti, da postignemo milosrđe i nađemo milost, kad nam ustreba pomoć! (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam djela svoja Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Hebr 4, 16) Pristupimo s pouzdanjem k prijestolju milosti, da postignemo milosrđe i nađemo milost, kad nam ustreba pomoć!"},"8a0ea850f04474c0":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji si u Srcu blažene Djevice Marije pripravio dostojno prebivalište Duhu Svetome, podaj milostivo, da mi koji odanom dušom slavimo svetkovinu (spomen) njezina bezgrješnog Srca uzmognemo živjeti po Srcu tvome.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"comemorationem → ∅"},"2de5fba36a04c0be":{"t":"Sir 24, 23-31\nČitanje knjige Mudrosti. Ja sam kao loza dala ugodan miris, a cvijeće moje rod je slavan i častan. Ja sam majka lijepe ljubavi, straha, znanja i svetoga ufanja. U meni je sva milina življenja i istine, u meni je sva nada života i kreposti. Dođite k meni svi koji me želite i nasitite se plodova mojih. Jer je duh moj slađi od meda i nasljedstvo je moje slađe od medenoga saća. Uspomena je moja trajna kroz naraštaje. Koji mene blaguju još će gladovati i koji mene piju još će žeđati. Tko mene sluša neće se postidjeti, i koji rade po meni neće griješiti. Koji mene slave imat će život vječni."},"e309722717802a35":{"t":"Ps 12, 6, Ps 44, 18\n(Ps 12, 6) Srce se moje veseli radi spasenja tvoga, klicat ću od radosti Gospodinu koji me je obdario, pjevat ću psalme imenu Gospodnjemu. (Ps 44, 18) Sjećat će se imena tvojega od koljena do koljena. Stoga će te narodi slaviti dovijeka.\n\nLk 1, 46-47\n<i>Aleluja</i>, <i>aleluja</i>.\nVeliča duša moja Gospodina. I raduje se duh moj u Bogu spasu mojemu. <i>Aleluja</i>."},"0768acb23b8db282":{"t":"Iv 19, 25-27\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Stajale su kod križa Isusova njegova Majka i sestra Majke njegove Marija Kleofina i Marija Magdalena. Kada dakle vidje Isus Majku i učenika, koga ljubljaše gdje stoji, reče svojoj Majci: Ženo, evo ti sina. Zatim reče učeniku: Evo ti majke. I od onoga časa uze je učenik k sebi.","kn":"t Slijedi sveto Evanđelje po Ivanu (19, 25-27). U ono vrijeme stajale su uz Isusov križ njegova majka i sestra njegove majke Marija, Kleofina i Marija Magdalena. Kad je Isus viidio majku i uz nju učenika, kojega je ljubio, reče svojoj majci: Ženo, evo ti sina! Zatim reče učeniku: Evo ti majke! I od onoga časa uze je učenik k sebi.","knRef":"Kniewald 1942, str. 710–711 (snimka 356) (OCR)"},"5ce3bebf6cd9e6fd":{"t":"Lk 1, 47 i 49\nRaduje se duh moj u Bogu spasu mojemu, jer mi učini velike stvari Svesilni, i sveto je ime njegovo."},"284087b0481852bc":{"t":"Prinoseći tvome veličanstvu neokaljanog Jaganjca molimo, Gospodine, da naša srca zapali onaj božanski oganj koji je neizrecivo rasplamtio Srce blažene Djevice Marije.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"006ab57f0d571d6b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o svetkovini</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"3021ca5e60ee0aaa":{"t":"Iv 19, 26-27\nIsus reče Majci svojoj: Ženo, evo ti sina! Zatim reče učeniku: Evo ti Majke! I od onoga časa uze je učenik sebi."},"f19c5bdd23db17a0":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni božanskim darovima ponizno te, Gospodine, molimo, da po zagovoru blažene Djevice Marije, koje smo svetkovinu (spomen) bezgrješnog Srca časno proslavili oslobođeni od sadašnjih pogibelji postignemo radosti vječnog života.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"memoriam → ∅"}}});
